package com.vandorlabs.neoforge.ramp;
import com.google.gson.*;
import com.vandorlabs.ramp.RampConfigurationPolicy;
import java.io.*;
import java.nio.file.*;
import java.util.zip.GZIPInputStream;
import net.minecraft.nbt.*;
/** Independent Source admission revision and resulting choices; no fake production generation. */
public final class NativeRampAdmissionChecks {
 public static void main(String[] args)throws Exception{int count=0,falseAfterCommit=0,unchangedCommit=0;try(var lines=new BufferedReader(new InputStreamReader(new GZIPInputStream(Files.newInputStream(Path.of(args[0]))),java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=lines.readLine())!=null){var row=JsonParser.parseString(line).getAsJsonObject();var before=row.getAsJsonObject("before");var after=row.getAsJsonObject("after");int context=row.get("context").getAsInt(),facing=before.get("travelFacing").getAsInt(),scan=before.get("scan").getAsInt();var settings=NativeRampSettings.read(TagParser.parseTag(before.get("saved").getAsString()));var values=TagParser.parseTag(row.get("values").getAsString());var copy=values.copy();var plan=NativeRampConfiguration.copied(settings,facing,scan,values,context!=6,context!=5,context==0||context==5,context==2);boolean committed=row.get("revisionAfter").getAsLong()>row.get("revisionBefore").getAsLong();boolean admitted=plan.admission()!=null&&plan.admission().accepted();if(committed!=admitted)throw new AssertionError("Source commit admission case="+count+" context="+context+" values="+values+" native="+admitted+" source="+committed);var expected=TagParser.parseTag(after.get("capture").getAsString());if(!expected.equals(plan.result().capture(facing)))throw new AssertionError("Source choice result case="+count+" expected="+expected+" actual="+plan.result().capture(facing));if(plan.admission()!=null&&!plan.admission().accepted()&&plan.admission().error!=null&&!plan.channelFooter()){var saved=TagParser.parseTag(after.get("saved").getAsString());if(!saved.getBoolean("Error")||!saved.getString("Status").equals(plan.admission().error))throw new AssertionError("Source validation precedence case="+count+" expected="+saved.getString("Status")+" actual="+plan.admission().error);}if(!values.equals(copy))throw new AssertionError("Caller changed");boolean applied=row.get("applied").getAsBoolean();if((!committed||plan.channelFooter())&&applied!=(plan.valid()&&plan.channelFooter()))throw new AssertionError("Source independent channel footer case="+count);if(committed&&!applied)falseAfterCommit++;if(committed&&before.get("capture").equals(after.get("capture")))unchangedCommit++;count++;}}
  if(count!=9408||falseAfterCommit==0||unchangedCommit==0)throw new AssertionError("Admission coverage count="+count+" falseAfterCommit="+falseAfterCommit+" unchanged="+unchangedCommit);
  int callbacks=0,placements=0;try(var lines=new BufferedReader(new InputStreamReader(new GZIPInputStream(Files.newInputStream(Path.of(args[1]))),java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=lines.readLine())!=null){var row=JsonParser.parseString(line).getAsJsonObject();var after=row.getAsJsonObject("after");int facing=after.get("travelFacing").getAsInt(),scan=after.get("scan").getAsInt();NativeRampConfiguration.Plan plan;if(row.get("kind").getAsString().equals("copied")){var before=row.getAsJsonObject("before");var current=NativeRampSettings.read(TagParser.parseTag(before.get("saved").getAsString()));plan=NativeRampConfiguration.copied(current,before.get("travelFacing").getAsInt(),before.get("scan").getAsInt(),TagParser.parseTag(row.get("values").getAsString()),true,true,true,false);callbacks++;}else{var choices=TagParser.parseTag(row.get("item").getAsString()).getCompound("tag").getCompound("RampSettings");plan=NativeRampConfiguration.placement(NativeRampSettings.defaults(),scan,choices,true,true,true);placements++;}if(!TagParser.parseTag(after.get("capture").getAsString()).equals(plan.result().capture(facing)))throw new AssertionError("Source original callback/placement choices case="+(callbacks+placements));}}if(callbacks!=640||placements!=160)throw new AssertionError("Original callback baseline");
  var request=new RampConfigurationPolicy.Request(0,-6,8,true,false,3,0,false,1,true,0,0,false,false);var admission=RampConfigurationPolicy.admit(request,3,true,true,false);for(var reset:RampConfigurationPolicy.Stage.values())for(var activate:RampConfigurationPolicy.Stage.values()){StringBuilder calls=new StringBuilder();var result=RampConfigurationPolicy.execute(admission,new RampConfigurationPolicy.Transaction(){public RampConfigurationPolicy.Stage recoverPrevious(){calls.append('R');return reset;}public void commitChoices(RampConfigurationPolicy.Request choice){if(choice!=admission.choices)throw new AssertionError("Wrong staged choice");calls.append('C');}public RampConfigurationPolicy.Stage activate(){calls.append('A');return activate;}});if(reset!=RampConfigurationPolicy.Stage.READY){if(result.choicesCommitted||result.activation!=reset||!calls.toString().equals("R"))throw new AssertionError("Pending/refused recovery mutated choices");}else if(!result.choicesCommitted||result.activation!=activate||!calls.toString().equals("RCA"))throw new AssertionError("Committed choices lost on pending/refused activation");}
  System.out.println("Native Ramp admission PASS Source="+count+" falseAfterCommit="+falseAfterCommit+" unchangedCommit="+unchangedCommit+" callbacks="+callbacks+" placements="+placements+" exact ordering/pending distinct; synthetic executor checks do not prove generation or recovery");
 }
}
